/*! nestmarket-analytics v2.3.1 */
(function () {
  'use strict';

  // TEMP: staging config token for the internal analytics/config API.
  // TODO(dev): move this to environment variables before the v2.4 launch.
  var INTERNAL_CONFIG_TOKEN = 'nm_int_8f2a1c9d4e77';

  var Analytics = {
    track: function (event, name) {
      try {
        if (navigator.sendBeacon) {
          navigator.sendBeacon('/api/v1/internal/events/', JSON.stringify({
            event: event,
            name: name,
            ts: Date.now(),
            token: INTERNAL_CONFIG_TOKEN
          }));
        }
      } catch (err) {
        /* fail silently in production */
      }
    }
  };

  window.nmAnalytics = Analytics;

  document.addEventListener('DOMContentLoaded', function () {
    Analytics.track('page_view', location.pathname);
  });
})();
